                    spf[j] = i
    return spf


def factorize(x, spf):
    res = []
    while x > 1:
        p = spf[x]
        cnt = 0
        while x % p == 0:
            x //= p
            cnt += 1
        res.append((p, cnt))
    return res


def contribution(p, exps):
    total = sum(exps)
    max_add = total

    for i, e in enumerate(exps, 1):
        max_add = max(max_add, i * e)

    pow_p = [1] * (max_add + 1)
    for i in range(max_add):
        pow_p[i + 1] = pow_p[i] * p % MOD

    dp = [0] * (total + 1)
    dp[0] = 1
    max_h = 0

    for i, e in enumerate(exps, 1):
        ndp = [0] * (total + 1)

        if e == 0:
            for h in range(max_h + 1):
                if dp[h]:
                    ndp[h] = dp[h] * pow_p[h] % MOD
        else:
            for h in range(max_h + 1):
                cur = dp[h]
                if cur == 0:
                    continue

                up = h + e
                ndp[up] = (ndp[up] + cur * pow_p[up]) % MOD

                if h >= e:
                    down = h - e
                    add = down
                else:
                    down = 0
                    add = i * (e - h)

                ndp[down] = (ndp[down] + cur * pow_p[add]) % MOD

            max_h += e

        dp = ndp

    return sum(dp) % MOD


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    spf = build_spf(MAX_A)
    exps_by_prime = {}

    for i, x in enumerate(a):
        for p, e in factorize(x, spf):
            if p not in exps_by_prime:
                exps_by_prime[p] = [0] * (n - 1)
            exps_by_prime[p][i] = e

    ans = 1
    for p, exps in exps_by_prime.items():
        ans = ans * contribution(p, exps) % MOD

    print(ans)


if __name__ == "__main__":
    main()
